@@@VIZ-START
<div style="padding: 24px; font-family: var(--font-sans); max-width: 600px;">
  <div style="margin-bottom: 16px;">
    <h3 style="margin: 0; font-size: 18px; font-weight: 500; color: var(--color-text-primary);">Monthly Costs</h3>
    <p style="margin: 4px 0 0; font-size: 13px; color: var(--color-text-secondary);">Expense tracking across four months</p>
  </div>
  <div style="position: relative; height: 280px;">
    <canvas id="costChart"></canvas>
  </div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded', () => {
  const s = getComputedStyle(document.documentElement);
  const textColor = s.getPropertyValue('--color-text-secondary').trim();
  const gridColor = s.getPropertyValue('--color-border-tertiary').trim();

  const ctx = document.getElementById('costChart').getContext('2d');

  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: ['Jan', 'Feb', 'Mar', 'Apr'],
      datasets: [{
        label: 'Cost',
        data: [12, 9, 15, 7],
        backgroundColor: '#1D9E75',
        borderRadius: 6,
        borderSkipped: false,
        barPercentage: 0.6
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      layout: { padding: 10 },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(255, 255, 255, 0.9)',
          titleColor: '#1f2937',
          bodyColor: '#4b5563',
          borderColor: '#e5e7eb',
          borderWidth: 1,
          padding: 10,
          cornerRadius: 6,
          displayColors: false,
          callbacks: {
            title: (ctx) => `Month: ${ctx[0].label}`,
            label: (ctx) => `Total cost: ${ctx.raw}`
          }
        }
      },
      scales: {
        x: {
          grid: { display: false },
          ticks: { color: textColor, font: { size: 12, weight: '500' } },
          border: { display: false }
        },
        y: {
          beginAtZero: true,
          max: 20,
          grid: { color: gridColor, drawBorder: false, tickLength: 6 },
          ticks: { color: textColor, font: { size: 12 }, stepSize: 5, padding: 8 },
          border: { display: false }
        }
      }
    }
  });
});
</script>
@@@VIZ-END

The chart displays the values clearly with rounded bars and adaptive theme colors. Hovering over any bar will show a detailed tooltip with the exact cost for that month. Let me know if you'd like to adjust the scale, add more data points, or change the visual style!

