var pods = [
  { x: 160, name: 'Pod 1', ip: '10.244.1.5:8080' },
  { x: 340, name: 'Pod 2', ip: '10.244.2.9:8080' },
  { x: 520, name: 'Pod 3', ip: '10.244.3.2:8080' }
];
var nextIdx = 0, count = 0, busy = false;
var dot = document.getElementById('dot');

function segLen(a, b) { return Math.hypot(b[0] - a[0], b[1] - a[1]); }

function animateTo(pod, done) {
  var pts = [[340, 78], [340, 206], [pod.x, 290]];
  var lens = [segLen(pts[0], pts[1]), segLen(pts[1], pts[2])];
  var total = lens[0] + lens[1];
  var t0 = null, speed = 550; // px per second

  dot.setAttribute('opacity', '1');
  function frame(ts) {
    if (!t0) t0 = ts;
    var d = (ts - t0) / 1000 * speed;
    var p;
    if (d <= lens[0]) {
      var f = d / lens[0];
      p = [pts[0][0] + (pts[1][0] - pts[0][0]) * f, pts[0][1] + (pts[1][1] - pts[0][1]) * f];
    } else {
      var f2 = (d - lens[0]) / lens[1];
      p = [pts[1][0] + (pts[2][0] - pts[1][0]) * f2, pts[1][1] + (pts[2][1] - pts[1][1]) * f2];
    }
    dot.setAttribute('cx', p[0]);
    dot.setAttribute('cy', p[1]);
    if (d < total) {
      requestAnimationFrame(frame);
    } else {
      dot.setAttribute('opacity', '0');
      done();
    }
  }
  requestAnimationFrame(frame);
}

function highlight(i) {
  var rect = document.getElementById('pod-rect-' + i);
  rect.classList.add('pod-hit');
  setTimeout(function () { rect.classList.remove('pod-hit'); }, 900);
}

function logRequest(n, pod) {
  var hint = document.getElementById('log-hint');
  if (hint && hint.parentNode) hint.parentNode.removeChild(hint);
  var log = document.getElementById('log');
  var line = document.createElement('div');
  line.className = 'line';
  line.innerHTML = 'req #' + n + ' → ' + pod.name + ' <b>(' + pod.ip + ')</b> · 200 OK';
  log.insertBefore(line, log.firstChild);
  while (log.children.length > 5) log.removeChild(log.lastChild);
}

function sendRequest() {
  if (busy) return;
  busy = true;
  var i = nextIdx % 3;
  nextIdx++;
  count++;
  animateTo(pods[i], function () {
    highlight(i);
    logRequest(count, pods[i]);
    busy = false;
  });
}
</script>
</div>
@@@VIZ-END

How it works in the diagram:

1. **Client** sends a request to the Service's DNS name (e.g. `svc-name.ns.svc.cluster.local`), which resolves to the **ClusterIP** `10.96.0.10:80`. That IP is virtual — it doesn't belong to any real interface.
2. **kube-proxy** programs iptables/IPVS rules on every node based on the Service's label selector (`app=web`). The matching ready Pods are recorded in an **EndpointSlice**. When a packet hits the ClusterIP, DNAT rewrites its destination to one of the listed Pod IPs — by default **round-robin** (with IPVS you can also use least-conn, etc.).
3. The packet is delivered to one of the **three Pods** on the pod network, which respond. Only Pods passing their **readiness probes** are in the endpoint list, so a bad Pod is excluded automatically.

Use the **Send request** button to see the load-balancing in action — each click lands on the next Pod in sequence, and the log tracks where each request went.

